/**
 * KalmiPrep Scientific Calculator - MathLive LaTeX to Mathematical Engine Converter
 * 
 * Safely converts structured LaTeX expressions generated by MathLive <math-field>
 * into computable mathematical representations for Math.js and Nerdamer.
 * Zero eval() or Function() constructor calls.
 * 
 * Handles:
 * - Nested fractions: \frac{a}{b} -> ((a) / (b))
 * - Powers & nested exponents: 2^{3^{2}} -> 2^(3^(2))
 * - Indexed roots: \sqrt[3]{27} -> nthRoot(27, 3)
 * - Square roots: \sqrt{16} -> sqrt(16)
 * - Arbitrary base logarithms: \log_{2}\left(32\right) -> log(32, 2)
 * - Common and natural logs: \log(x) -> log(x, 10), \ln(x) -> ln(x)
 * - Trigonometric & inverse trigonometric functions: \sin, \cos, \tan, \sin^{-1}, etc.
 * - Absolute values: \left|x\right| -> abs(x)
 * - Factorials: x! -> factorial(x)
 * - Combinatorics: nPr, nCr
 * - Constants & Scientific notation: \pi -> pi, e -> e, \times 10^{x} -> *10^(x)
 * - Implicit multiplication: 2\pi -> 2*pi, 2(3) -> 2*(3)
 */

(function (global) {
  'use strict';

  function parseBraces(str, startIndex) {
    let depth = 0;
    let start = -1;
    for (let i = startIndex; i < str.length; i++) {
      if (str[i] === '{') {
        if (depth === 0) start = i + 1;
        depth++;
      } else if (str[i] === '}') {
        depth--;
        if (depth === 0) {
          return { content: str.slice(start, i), nextIndex: i + 1 };
        }
      }
    }
    return null;
  }

  /**
   * Converts a MathLive LaTeX expression string into a computable math string.
   * 
   * @param {string} latex Raw LaTeX from MathLive
   * @param {number|string} lastAns Previous answer value
   * @returns {string} Clean computable expression string for Math.js
   */
  function latexToMath(latex, lastAns = 0) {
    if (!latex || !latex.trim()) return '0';

    let s = latex.trim();

    // 1. Remove empty placeholder markers & invisible tokens
    s = s.replace(/\\Box/g, '');
    s = s.replace(/\\placeholder\{[^\}]*\}/g, '');
    s = s.replace(/\\left/g, '').replace(/\\right/g, '');
    s = s.replace(/\\mleft/g, '').replace(/\\mright/g, '');

    // 2. Handle nested stacked fractions recursively: \frac{num}{den} -> ((num)/(den))
    let loopCount = 0;
    while (s.includes('\\frac') && loopCount < 30) {
      loopCount++;
      const idx = s.indexOf('\\frac');
      const numObj = parseBraces(s, idx + 5);
      if (!numObj) break;
      const denObj = parseBraces(s, numObj.nextIndex);
      if (!denObj) break;
      const converted = '((' + latexToMath(numObj.content, lastAns) + ') / (' + latexToMath(denObj.content, lastAns) + '))';
      s = s.slice(0, idx) + converted + s.slice(denObj.nextIndex);
    }

    // 3. Handle indexed general roots: \sqrt[n]{x} -> nthRoot(x, n)
    s = s.replace(/\\sqrt\[([^\]]+)\]\{([^\}]+)\}/g, (m, n, x) => {
      return 'nthRoot(' + latexToMath(x, lastAns) + ', ' + latexToMath(n, lastAns) + ')';
    });

    // 4. Handle square roots: \sqrt{x} -> sqrt(x)
    loopCount = 0;
    while (s.includes('\\sqrt{') && loopCount < 30) {
      loopCount++;
      const idx = s.indexOf('\\sqrt{');
      const bodyObj = parseBraces(s, idx + 5);
      if (!bodyObj) break;
      const converted = 'sqrt(' + latexToMath(bodyObj.content, lastAns) + ')';
      s = s.slice(0, idx) + converted + s.slice(bodyObj.nextIndex);
    }

    // 5. Handle arbitrary base logarithms: \log_{b}(x) -> log(x, b)
    s = s.replace(/\\log_\{([^\}]+)\}\(([^\)]+)\)/g, (m, base, arg) => {
      return 'log(' + latexToMath(arg, lastAns) + ', ' + latexToMath(base, lastAns) + ')';
    });
    s = s.replace(/\\log_([0-9a-zA-Z]+)\(([^\)]+)\)/g, (m, base, arg) => {
      return 'log(' + latexToMath(arg, lastAns) + ', ' + base + ')';
    });

    // 6. Handle scientific exponential notation: \times 10^{exp} -> *10^(exp)
    s = s.replace(/\\times\s*10\^\{([^\}]+)\}/g, (m, exp) => '*10^(' + latexToMath(exp, lastAns) + ')');
    s = s.replace(/\\cdot\s*10\^\{([^\}]+)\}/g, (m, exp) => '*10^(' + latexToMath(exp, lastAns) + ')');

    // 7. Handle absolute value: |x| -> abs(x)
    s = s.replace(/\|([^\|]+)\|/g, (m, body) => 'abs(' + latexToMath(body, lastAns) + ')');

    // 8. Replace mathematical functions & operators
    s = s
      .replace(/\\times/g, '*')
      .replace(/\\div/g, '/')
      .replace(/\\cdot/g, '*')
      .replace(/\\pi/g, 'pi')
      .replace(/\\mathrm\{Ans\}/gi, `(${parseFloat(lastAns) || 0})`)
      .replace(/\\text\{Ans\}/gi, `(${parseFloat(lastAns) || 0})`)
      .replace(/\\mathrm\{P\}/g, ' nPr ')
      .replace(/\\mathrm\{C\}/g, ' nCr ')
      .replace(/\\sin\^\{-1\}/g, 'asin')
      .replace(/\\cos\^\{-1\}/g, 'acos')
      .replace(/\\tan\^\{-1\}/g, 'atan')
      .replace(/\\arcsin/g, 'asin')
      .replace(/\\arccos/g, 'acos')
      .replace(/\\arctan/g, 'atan')
      .replace(/\\sin/g, 'sin')
      .replace(/\\cos/g, 'cos')
      .replace(/\\tan/g, 'tan')
      .replace(/\\ln/g, 'ln')
      .replace(/\\log/g, 'log')
      .replace(/\\{/g, '(')
      .replace(/\\}/g, ')');

    // 9. Handle exponent braces with balanced braces: ^{expr} -> ^(expr)
    loopCount = 0;
    while (s.includes('^{') && loopCount < 30) {
      loopCount++;
      const idx = s.indexOf('^{');
      const expObj = parseBraces(s, idx + 1);
      if (!expObj) break;
      const converted = '^(' + latexToMath(expObj.content, lastAns) + ')';
      s = s.slice(0, idx) + converted + s.slice(expObj.nextIndex);
    }

    // 10. Fix implicit multiplications:
    // e.g. 2pi -> 2*pi, 2(3) -> 2*(3), ) ( -> )*(
    s = s.replace(/(\d)\s*(pi|e|sin|cos|tan|asin|acos|atan|ln|log|sqrt|nthRoot|abs)\b/g, '$1*$2');
    s = s.replace(/(\d)\s*\(/g, '$1*(');
    s = s.replace(/\)\s*\(/g, ')*(');
    s = s.replace(/\)\s*(\d)/g, ')*$1');
    s = s.replace(/\)\s*(pi|e)\b/g, ')*$1');

    return s;
  }

  const KalmiCalcConverter = {
    latexToMath,
  };

  // Export
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = KalmiCalcConverter;
  }
  if (typeof global !== 'undefined') {
    global.KalmiCalcConverter = KalmiCalcConverter;
  }
})(typeof window !== 'undefined' ? window : globalThis);
